async function establishSession(){state.boot=await api('getBootstrap');const i=state.boot.identity;state.personId=i.personId;const own=state.boot.members.find(p=>p.PersonId===i.personId);if(own){state.teamId=own.TeamId;setData(await api('loadAssessment',{year:state.boot.roundId,personId:i.personId}));state.mode='member';state.view='dashboard';}else{state.mode='member';state.view='overview';state.data=null;}render();}
document.addEventListener('submit',async e=>{if(e.target.id!=='loginForm')return;e.preventDefault();const button=e.target.querySelector('button[type=submit]');button.disabled=true;$('loginError').textContent='กำลังตรวจสอบบัญชี…';try{const login=await gasRequest('login',{request:{username:$('loginUsername').value,password:$('loginPassword').value}});$('loginPassword').value='';state.token=login.token;sessionStorage.setItem('svs-session',login.token);await establishSession();}catch(error){if($('loginError'))$('loginError').textContent=error.message||'เข้าสู่ระบบไม่สำเร็จ';}finally{button.disabled=false;}});
function applyRoleUI(){const i=state.boot.identity;document.querySelector('header').style.display='';$('tabAdmin').style.display=state.boot.isAdmin?'':'none';$('tabHead').style.display=i.canHead?'':'none';$('tabSponsor').style.display=i.canSponsor?'':'none';$('tabMember').style.display=state.boot.members.length?'':'none';$('tabMember').textContent=i.roles.includes('Member')?'ประเมิน KPI ของฉัน':'ข้อมูลสมาชิก';$('signedIdentity').textContent=i.name+' · '+i.username;}
function lockSponsorUI(){if(state.sponsor?.canEdit===false)document.querySelectorAll('[data-sponsor-score],[data-sponsor-notes],[data-action="save-project"]').forEach(el=>el.disabled=true);}
function permittedPreview(r){if(!state.boot.privateScores)return r;r.kpis=r.kpis.map(k=>k.project?{...k,raw:null,percent:null,grade:null,weighted:null,complete:false,hidden:true,reason:'คะแนนเฉพาะผู้มีสิทธิ์'}:k);r.total=null;r.partial=null;r.complete=false;r.completed=r.kpis.filter(k=>!k.project&&k.applicable&&k.complete).length;r.required=r.kpis.filter(k=>!k.project&&k.applicable).length;r.privateScores=true;return r;}
function evidenceLink(kpi,id){const url=kpi?.[id];return safeHeadLink(url)?`<br><a href="${esc(url)}" target="_blank" rel="noopener">หลักฐาน ${esc(id)} ↗</a>`:'';}
function renderUsers(){const list=state.accessUsers||[];$('app').innerHTML=`<div class="intro row"><h1>บัญชีผู้ใช้งาน</h1><button class="alt" data-action="mode-admin">← กลับ Admin</button></div><section class="box"><p>รหัสผ่านแสดงเฉพาะครั้งที่รีเซ็ต ระบบไม่เก็บรหัสผ่านแบบอ่านข้อความได้</p><div class="tablewrap"><table><thead><tr><th>Username</th><th>ชื่อ</th><th>บทบาท</th><th>สถานะ</th><th>จัดการ</th></tr></thead><tbody>${list.map(u=>`<tr><td>${esc(u.username)}</td><td>${esc(personName(u.personId))}</td><td>${esc(u.roles)}</td><td>${u.locked?'พักชั่วคราว':u.active?'ใช้งาน':'ปิด'}</td><td><button class="alt" data-action="reset-password" data-username="${esc(u.username)}">รีเซ็ตรหัสผ่าน</button></td></tr>`).join('')}</tbody></table></div><div id="resetResult" role="status"></div></section>`;}
async function authUiAction(a,b){if(a==='toggle-password'){$('loginPassword').type=$('loginPassword').type==='password'?'text':'password';b.textContent=$('loginPassword').type==='password'?'แสดง':'ซ่อน';return true;}if(a==='logout'){if(state.dirty){await saveCurrent(false);if(state.dirty||state.saveError||state.conflict){toast('บันทึกข้อมูลให้เรียบร้อยก่อนออกจากระบบ',true);return true;}}try{await gasRequest('logout',{token:state.token});}catch(e){if(!String(e.message).includes('AUTH_REQUIRED')){toast('ออกจากระบบไม่สำเร็จ กรุณาลองใหม่',true);return true;}}authClear();return true;}if(a==='access-users'){await task(async()=>{state.accessUsers=await api('getAccessUsers');state.mode='users';renderUsers();});return true;}if(a==='reset-password'){if(!confirm('สร้างรหัสผ่านใหม่ให้ '+b.dataset.username+'? การเข้าสู่ระบบเดิมของบัญชีนี้จะหมดอายุ'))return true;await task(async()=>{const r=await api('resetUserPassword',{username:b.dataset.username});$('resetResult').innerHTML=`<div class="notice"><b>${esc(r.username)}</b><p>รหัสผ่านใหม่: <code>${esc(r.password)}</code></p><p>แจ้งเจ้าของบัญชีเป็นการส่วนตัว แล้วออกจากหน้านี้</p></div>`;});return true;}if(a==='unlock-assessment'){if(!confirm('เปิดแบบประเมินนี้ให้สมาชิกแก้ไขอีกครั้ง?'))return true;await task(async()=>{await api('unlockAssessment',{personId:state.personId,year:state.boot.roundId});setData(await api('loadAssessment',{personId:state.personId,year:state.boot.roundId}));render();});return true;}return false;}

function clone(x){return JSON.parse(JSON.stringify(x));}
function normal(a){return {Applicability:a?.Applicability||'Applicable',Score:a?.Score??'',Notes:String(a?.Notes||''),EvidenceUrl:String(a?.EvidenceUrl||'')};}
function memberSnapshot(){return {kpiEvidence:clone(state.evidenceByKpi||{}),answers:clone(state.answers),group:state.group,route:state.route,evidence:state.evidence||''};}
function changesFrom(base,local){const before={};base.answers.forEach(a=>before[a.CriterionId]=a);return Object.entries(local.answers).filter(([id,a])=>JSON.stringify(normal(a))!==JSON.stringify(normal(before[id]))).map(([id,a])=>({criterionId:id,applicability:a.Applicability||'Applicable',score:a.Score??'',notes:a.Notes||'',base:normal(before[id])}));}
function pendingMember(){if(!state.data||readonly())return false;const a=state.data.assessment;return JSON.stringify(state.evidenceByKpi||{})!==JSON.stringify(state.data.kpiEvidence||{})||changesFrom(state.data,memberSnapshot()).length>0||state.group!==a.CustomerGroup||state.route!==(a.Kpi5Route||'')||(state.evidence||'')!==(a.EvidenceUrl||'');}
function syncStatus(){return state.saving?'กำลังบันทึกร่าง…':state.conflict?'รอตรวจข้อมูลที่แก้ไขชนกัน':state.saveError?'บันทึกไม่สำเร็จ — ข้อมูลยังอยู่ในหน้านี้':state.dirty?'มีข้อมูลรอบันทึกอัตโนมัติ':'บันทึกล่าสุดแล้ว';}
function updateStatus(){if(state.mode==='member'&&state.data&&state.view!=='profile'&&state.view!=='overview'&&state.view!=='report')renderBottom(result());const el=$('sponsorSaveStatus');if(el)el.textContent=syncStatus();}
function markDirty(){state.dirty=true;state.saveError='';clearTimeout(state.autoTimer);state.autoTimer=setTimeout(()=>{if(!state.conflict)saveCurrent(false);},2000);updateStatus();}
async function saveCurrent(submit=false){if(state.mode==='sponsor')return saveSponsorDraft();return save(submit);}
function mergeObject(base,local,remote){const out={...remote},conflicts=[];for(const key of Object.keys(local)){if(JSON.stringify(local[key])===JSON.stringify(base?.[key]))continue;if(JSON.stringify(remote?.[key])!==JSON.stringify(base?.[key])&&JSON.stringify(remote?.[key])!==JSON.stringify(local[key]))conflicts.push(key);out[key]=local[key];}return {out,conflicts};}
function applyResponse(response,sent){const now=memberSnapshot();setData(response);for(const id of Object.keys(now.kpiEvidence)){if(now.kpiEvidence[id]!==sent.kpiEvidence[id])state.evidenceByKpi[id]=now.kpiEvidence[id];}for(const [id,a] of Object.entries(now.answers)){if(JSON.stringify(normal(a))!==JSON.stringify(normal(sent.answers[id])))state.answers[id]=a;}if(now.group!==sent.group)state.group=now.group;if(now.route!==sent.route)state.route=now.route;if(now.evidence!==sent.evidence)state.evidence=now.evidence;state.dirty=pendingMember();}
async function save(submit=false){
 clearTimeout(state.autoTimer);if(state.saving){await state.savePromise;if(state.conflict)return;if(submit||pendingMember())return save(submit);return;}
 if(!state.data||readonly()||(!submit&&!pendingMember())){state.dirty=false;updateStatus();return;}
 if(submit&&!confirm('ส่งผลประเมินตนเอง? ตรวจข้อมูลให้ครบก่อนส่ง หลังส่งต้องให้ผู้ดูแลเปิดแก้ไข'))return;
 const sent=memberSnapshot(),base=clone(state.data),a=base.assessment;
 const req={kpiEvidence:sent.kpiEvidence,baseKpiEvidence:base.kpiEvidence||{},year:a.RoundId,personId:a.PersonId,customerGroup:sent.group,kpi5Route:sent.route,evidenceUrl:sent.evidence,revision:a.Revision,policyRevision:base.policy.revision,patch:true,baseMeta:{customerGroup:a.CustomerGroup,kpi5Route:a.Kpi5Route||'',evidenceUrl:a.EvidenceUrl||''},answers:changesFrom(base,sent)};
 state.saving=true;state.saveError='';updateStatus();
 state.savePromise=(async()=>{try{const response=await api(submit?'submitAssessment':'saveAssessment',req);if(response.conflict){state.conflict={type:'member',base,local:memberSnapshot(),latest:response.latest,message:response.message};renderConflict();return;}applyResponse(response,sent);state.lastSaved=new Date();if(!submit)toast('✓ บันทึกข้อมูลเรียบร้อยแล้ว · '+new Date().toLocaleTimeString('th-TH'));if(submit){state.view='dashboard';state.activeKpi=null;render();toast('ส่งผลประเมินตนเองแล้ว');}}catch(e){state.saveError=e.message||String(e);toast(state.saveError+' ข้อมูลยังอยู่ในหน้านี้ กรุณากดบันทึกอีกครั้ง',true);}finally{state.saving=false;updateStatus();if(state.dirty&&!state.conflict&&!state.saveError){clearTimeout(state.autoTimer);state.autoTimer=setTimeout(()=>save(false),2000);}}})();await state.savePromise;
}
function setSponsor(data){state.sponsor=data;state.sponsorBase=clone(data);state.dirty=false;state.saveError='';}
async function saveSponsorDraft(){
 clearTimeout(state.autoTimer);if(state.saving){await state.savePromise;if(state.dirty&&!state.conflict)return saveSponsorDraft();return;}if(!state.sponsor||!state.dirty)return;
 const sent=clone(state.sponsor),base=clone(state.sponsorBase),p=sent.projects.find(p=>p.projectId===state.projectId),bp=base.projects.find(x=>x.projectId===p.projectId);
 const scores=p.people.filter(x=>{const b=bp.people.find(y=>y.personId===x.personId);return x.score!==b.score||(x.notes||'')!==(b.notes||'');}).map(x=>{const b=bp.people.find(y=>y.personId===x.personId);return {...x,base:{score:b.score??'',notes:b.notes||''}};});
 if(!scores.length){state.dirty=false;updateStatus();return;}state.saving=true;state.saveError='';updateStatus();
 state.savePromise=(async()=>{try{const response=await api('saveSponsorScores',{year:sent.roundId,sponsorId:sent.sponsorId,projectId:p.projectId,patch:true,scores});const now=clone(state.sponsor);setSponsor(response);toast('✓ บันทึกคะแนนเรียบร้อยแล้ว · '+new Date().toLocaleTimeString('th-TH'));for(const np of now.projects){const sp=sent.projects.find(x=>x.projectId===np.projectId),rp=state.sponsor.projects.find(x=>x.projectId===np.projectId);if(!rp||!sp)continue;for(const n of np.people){const previous=sp.people.find(x=>x.personId===n.personId),fresh=rp.people.find(x=>x.personId===n.personId);if(!fresh)continue;if(n.score!==previous.score){fresh.score=n.score;state.dirty=true;}if((n.notes||'')!==(previous.notes||'')){fresh.notes=n.notes;state.dirty=true;}}}if(!state.dirty&&state.mode==='sponsor'&&!['TEXTAREA','SELECT'].includes(document.activeElement?.tagName))renderSponsor();}
 catch(e){state.saveError=e.message||String(e);if(state.saveError.includes('CONFLICT_SPONSOR')){const latest=await api('getSponsorPanel',{year:sent.roundId,sponsorId:sent.sponsorId});state.conflict={type:'sponsor',base,local:clone(state.sponsor),latest,message:'มีการแก้คะแนนช่องเดียวกันต่างค่าจากอีกหน้าต่าง กรุณาตรวจข้อมูลก่อนเลือก'};renderConflict();}else toast(state.saveError+' กรุณากดบันทึกอีกครั้ง',true);}
 finally{state.saving=false;updateStatus();if(state.dirty&&!state.conflict&&!state.saveError)state.autoTimer=setTimeout(()=>saveSponsorDraft(),2000);}})();await state.savePromise;
}
function renderConflict(){const box=$('conflictPanel');if(!state.conflict){box.innerHTML='';return;}const c=state.conflict,rows=[];if(c.type==='member'){for(const [id,a] of Object.entries(c.local.answers)){const b=c.base.answers.find(x=>x.CriterionId===id),r=c.latest.answers.find(x=>x.CriterionId===id);if(JSON.stringify(normal(a))!==JSON.stringify(normal(b)))rows.push([id,String(a.Score??'—'),String(r?.Score??'—')]);}}else{for(const p of c.local.projects){const bp=c.base.projects.find(x=>x.projectId===p.projectId),rp=c.latest.projects.find(x=>x.projectId===p.projectId);for(const x of p.people){const b=bp?.people.find(y=>y.personId===x.personId),r=rp?.people.find(y=>y.personId===x.personId);if(x.score!==b?.score||(x.notes||'')!==(b?.notes||''))rows.push([x.name,String(x.score||'—'),String(r?.score||'—')]);}}}
 box.innerHTML=`<section class="box conflict-box"><h2>ตรวจข้อมูลก่อนบันทึก</h2><p>${esc(c.message)}</p><table><thead><tr><th>หัวข้อ / สมาชิก</th><th>ที่กรอกในหน้านี้</th><th>ล่าสุดในระบบ</th></tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table><p class="muted">ข้อมูลที่กรอกยังอยู่ เลือกวิธีจัดการเฉพาะช่องที่แก้ไขชนกัน ก่อนบันทึกต่อ</p><div class="actions"><button data-action="resolve-local">ใช้ข้อมูลที่ฉันกรอก</button><button class="alt" data-action="resolve-remote">ใช้ข้อมูลล่าสุดในระบบ</button></div></section>`;box.scrollIntoView({behavior:'smooth',block:'start'});
}
function resolveConflict(preferLocal){const c=state.conflict;if(!c)return;const choose=(base,local,remote)=>{const out={...remote};for(const key of Object.keys(local)){if(JSON.stringify(local[key])===JSON.stringify(base?.[key]))continue;const collision=JSON.stringify(remote?.[key])!==JSON.stringify(base?.[key])&&JSON.stringify(remote?.[key])!==JSON.stringify(local[key]);if(!collision||preferLocal)out[key]=local[key];}return out;};
 if(c.type==='member'){setData(c.latest);state.evidenceByKpi=choose(c.base.kpiEvidence||{},c.local.kpiEvidence||{},c.latest.kpiEvidence||{});for(const [id,a] of Object.entries(c.local.answers)){if(!c.latest.policy.criteria.some(x=>x.CriterionId===id))continue;const base=c.base.answers.find(x=>x.CriterionId===id),remote=c.latest.answers.find(x=>x.CriterionId===id);state.answers[id]={CriterionId:id,...choose(normal(base),normal(a),normal(remote))};}const values=choose({group:c.base.assessment.CustomerGroup,route:c.base.assessment.Kpi5Route||'',evidence:c.base.assessment.EvidenceUrl||''},{group:c.local.group,route:c.local.route,evidence:c.local.evidence},{group:c.latest.assessment.CustomerGroup,route:c.latest.assessment.Kpi5Route||'',evidence:c.latest.assessment.EvidenceUrl||''});Object.assign(state,values);state.dirty=pendingMember();}
 else{setSponsor(c.latest);for(const p of c.local.projects){const bp=c.base.projects.find(x=>x.projectId===p.projectId),rp=state.sponsor.projects.find(x=>x.projectId===p.projectId);if(!rp)continue;for(const x of p.people){const b=bp?.people.find(y=>y.personId===x.personId),r=rp.people.find(y=>y.personId===x.personId);if(r)Object.assign(r,choose({score:b?.score??'',notes:b?.notes||''},{score:x.score??'',notes:x.notes||''},{score:r.score??'',notes:r.notes||''}));}}state.dirty=true;}
 state.conflict=null;state.saveError='';renderConflict();render();if(state.dirty)markDirty();
}
function evidenceSection(){
 const kpis=state.data.policy.kpis.filter(k=>!state.activeKpi||k.KpiId===state.activeKpi),folders=state.data.evidenceFolders||{};
 return `<section class="box evidence-section"><h2>โฟลเดอร์หลักฐานแยกตาม KPI</h2><p class="muted">กดเปิดโฟลเดอร์เพื่ออัปโหลดไฟล์ใน Google Drive</p>${kpis.map(k=>`<div class="field"><strong>${esc(k.KpiId)} · ${esc(k.Title)}</strong><br>${safeHeadLink(folders[k.KpiId])?`<a class="evidence-open" href="${esc(folders[k.KpiId])}" target="_blank" rel="noopener">เปิดโฟลเดอร์ ${esc(k.KpiId)} เพื่ออัปโหลดหลักฐาน ↗</a>`:'<span class="muted">ยังไม่พบโฟลเดอร์หลักฐาน กรุณาติดต่อผู้ดูแล</span>'}</div>`).join('')}</section>`;
}
function adminRow(){return state.admin?.years.find(y=>y.year===state.adminYear);}
function adminField(label,value,scope,index,key,type='text'){return `<label class="admin-field"><span>${label}</span>${type==='textarea'?`<textarea data-admin-scope="${scope}" data-index="${index}" data-key="${key}">${esc(value??'')}</textarea>`:`<input type="${type}" data-admin-scope="${scope}" data-index="${index}" data-key="${key}" value="${esc(value??'')}">`}</label>`;}
function renderAdmin(){if(!state.admin){$('app').innerHTML='<section class="box"><h1>Admin · จัดการเกณฑ์รายปี</h1><p>หน้านี้จำกัดเฉพาะบัญชีเจ้าของระบบ กรุณาเปิดเว็บโดยลงชื่อเข้าใช้ Google บัญชีเจ้าของ</p></section>';return;}const row=adminRow(),p=state.adminPolicy;
 $('app').innerHTML=`<div class="intro row"><div><h1>Admin · SVS Individual-KPI</h1><button class="alt" data-action="access-users">จัดการบัญชีผู้ใช้</button><p class="muted">แก้ฉบับร่าง แล้วตรวจและเผยแพร่ ปีเก่าเก็บแยกจากปีใหม่</p></div><span class="tag">ปีปัจจุบัน ${esc(state.admin.activeYear)}</span></div><section class="box"><div class="admin-toolbar"><label>ปีที่แก้ไข<select id="adminYear">${state.admin.years.map(y=>`<option value="${esc(y.year)}" ${y.year===state.adminYear?'selected':''}>${esc(y.year)} · ${y.published?'เผยแพร่แล้ว':'ฉบับร่าง'}</option>`).join('')}</select></label><label>สร้างปีใหม่โดยคัดลอกจากปีนี้<input id="newYear" type="number" min="2026" max="2099" value="${Number(state.adminYear)+1}"></label><button data-action="admin-create-year">สร้างปีใหม่</button><button class="alt" data-action="admin-reload">โหลดข้อมูล Admin ใหม่</button><button class="alt" data-action="admin-sync-projects">คัดลอกรายชื่อโครงการล่าสุดจากชีตเข้าเกณฑ์ร่าง</button></div><div class="notice">การบันทึกฉบับร่างยังไม่เปลี่ยนเกณฑ์ที่สมาชิกใช้งาน การเผยแพร่จะตรวจน้ำหนักทั้งสองกลุ่มให้รวม 100% และตรวจเกณฑ์คะแนนให้ครบ ผลที่ส่งแล้วใช้เกณฑ์เดิมที่บันทึกไว้</div><h2>เปอร์เซ็นต์ขั้นต่ำของแต่ละเกรด</h2><div class="admin-grid">${[2,3,4,5].map((g,i)=>adminField('เกรด '+g+' เริ่มที่ (%)',p.bands[i],'band',i,'value','number')).join('')}</div><div class="actions"><button data-action="admin-save">บันทึกฉบับร่าง</button><button data-action="admin-publish">ตรวจและเผยแพร่เกณฑ์ปี ${esc(state.adminYear)}</button><button class="alt" data-action="admin-activate" ${row.published?'':'disabled'}>ใช้ปีนี้เป็นปีปัจจุบัน</button></div></section><section class="box"><div class="row"><h2>หัวข้อ KPI หลัก · ${p.kpis.length} ข้อ</h2><button data-action="admin-add-kpi">เพิ่ม KPI</button></div><p class="muted">น้ำหนักรวม: ดูแลลูกค้า ${p.kpis.reduce((s,k)=>s+Number(k.WeightCustomer)*100,0).toFixed(2)}% · ไม่ดูแลลูกค้า ${p.kpis.reduce((s,k)=>s+Number(k.WeightNoCustomer)*100,0).toFixed(2)}%</p></section>${p.kpis.map((k,i)=>`<section class="box admin-kpi"><div class="row"><h2>${i+1}. ${esc(k.KpiId)} ${esc(k.Title)}</h2><button class="alt" data-action="admin-remove-kpi" data-index="${i}">นำ KPI นี้ออกจากฉบับร่าง</button></div><div class="admin-grid">${adminField('ชื่อหัวข้อ',k.Title,'kpi',i,'Title')}${adminField('วัตถุประสงค์',k.Objective,'kpi',i,'Objective','textarea')}${adminField('ทิศทางกลยุทธ์',k.StrategicDirection,'kpi',i,'StrategicDirection')}${adminField('Individual KPI',k.IndividualKPI,'kpi',i,'IndividualKPI','textarea')}${adminField('หลักการคำนวณ',k.Calculation,'kpi',i,'Calculation','textarea')}${adminField('น้ำหนัก: ดูแลลูกค้า (%)',Number(k.WeightCustomer)*100,'kpi',i,'WeightCustomer','number')}${adminField('น้ำหนัก: ไม่ดูแลลูกค้า (%)',Number(k.WeightNoCustomer)*100,'kpi',i,'WeightNoCustomer','number')}<label class="admin-field"><span>วิธีคำนวณข้อย่อย</span><select data-admin-scope="kpi" data-index="${i}" data-key="ScoreMode">${[['weighted','เฉลี่ย / ถ่วงน้ำหนักกลุ่ม'],['highest','ใช้คะแนนหัวข้อสูงสุด'],['project','คะแนนโครงการจาก Sponsor'],['legacy','ประเภทผลงานแบบเดิม']].map(([v,t])=>`<option value="${v}" ${(k.ScoreMode||(k.KpiId==='KPI6'?'project':k.KpiId==='KPI5'?'legacy':'weighted'))===v?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="row"><h3>ข้อย่อยและเกณฑ์ 1–5</h3><button class="alt" data-action="admin-add-criterion" data-id="${esc(k.KpiId)}">เพิ่มข้อย่อย</button></div>${p.criteria.map((c,ci)=>({c,ci})).filter(x=>x.c.KpiId===k.KpiId).map(({c,ci},j)=>`<details class="admin-criterion"><summary>${i+1}.${j+1} ${esc(c.Title)} · ${esc(c.CriterionId)}</summary><div class="admin-grid">${adminField('ชื่อข้อย่อย',c.Title,'criterion',ci,'Title')}${adminField('เป้าหมาย',c.Target,'criterion',ci,'Target')}${adminField('รายละเอียดหลักฐาน',c.Evidence,'criterion',ci,'Evidence','textarea')}${adminField('ชื่อกลุ่มกิจกรรม',c.GroupTitle,'criterion',ci,'GroupTitle')}${adminField('รหัสกลุ่ม (กลุ่มเดียวกันเฉลี่ยเท่ากัน)',c.GroupId,'criterion',ci,'GroupId')}${adminField('น้ำหนักกลุ่มย่อย (%)',Number(c.GroupWeight)*100,'criterion',ci,'GroupWeight','number')}${adminField('รหัสประเภทผลงาน (ถ้ามี)',c.Route,'criterion',ci,'Route')}${[1,2,3,4,5].map(n=>adminField('เกณฑ์คะแนน '+n,c['Grade'+n],'criterion',ci,'Grade'+n,'textarea')).join('')}<label><input type="checkbox" data-admin-scope="criterion" data-index="${ci}" data-key="AllowNA" ${c.AllowNA?'checked':''}>อนุญาตให้เลือกไม่เกี่ยวข้อง</label></div><button class="alt" data-action="admin-remove-criterion" data-index="${ci}">นำข้อย่อยนี้ออกจากฉบับร่าง</button></details>`).join('')}</section>`).join('')}<div class="sticky"><div class="inner"><b>Admin · แก้ปี ${esc(state.adminYear)} ${state.adminDirty?'· มีการแก้ไขที่ยังไม่บันทึก':''}</b><div class="actions"><button class="alt" data-action="admin-save">บันทึกฉบับร่าง</button><button data-action="admin-publish">ตรวจและเผยแพร่</button></div></div></div>`;
}
function setAdmin(data,year){state.admin=data;state.adminYear=year&&data.years.some(y=>y.year===year)?year:data.activeYear;state.adminPolicy=clone(adminRow().draft);state.adminDirty=false;}
async function adminAction(action,b){if(action==='admin-add-kpi'){const p=state.adminPolicy,n=Math.max(0,...p.kpis.map(k=>Number(k.KpiId.replace(/\D/g,''))||0))+1;p.kpis.push({KpiId:'KPI'+n,Title:'หัวข้อใหม่',Objective:'',WeightCustomer:0,WeightNoCustomer:0,Active:true,StrategicDirection:'',IndividualKPI:'',Calculation:'',ScoreMode:'weighted'});state.adminDirty=true;renderAdmin();return;}
 if(action==='admin-remove-kpi'){if(!confirm('นำหัวข้อนี้และข้อย่อยออกจากฉบับร่าง? เกณฑ์ที่เผยแพร่ยังไม่เปลี่ยนจนกว่าจะเผยแพร่ใหม่'))return;const k=state.adminPolicy.kpis.splice(Number(b.dataset.index),1)[0];state.adminPolicy.criteria=state.adminPolicy.criteria.filter(c=>c.KpiId!==k.KpiId);state.adminDirty=true;renderAdmin();return;}
 if(action==='admin-add-criterion'){const id='C'+Date.now().toString(36),ki=b.dataset.id;state.adminPolicy.criteria.push({CriterionId:id,KpiId:ki,GroupId:id,GroupTitle:'กิจกรรมใหม่',GroupWeight:1,Route:'',Title:'ข้อย่อยใหม่',Target:'',Evidence:'',Grade1:'',Grade2:'',Grade3:'',Grade4:'',Grade5:'',Active:true,AllowNA:false});state.adminDirty=true;renderAdmin();return;}
 if(action==='admin-remove-criterion'){state.adminPolicy.criteria.splice(Number(b.dataset.index),1);state.adminDirty=true;renderAdmin();return;}
 await task(async()=>{if(action==='admin-create-year'){if(state.adminDirty&&!confirm('มีฉบับร่างที่ยังไม่บันทึก ต้องการสร้างปีใหม่ต่อหรือไม่?'))return;const year=$('newYear').value;setAdmin(await api('createPolicyYear',{year,copyFrom:state.adminYear}),year);}
 else if(action==='admin-reload'){if(state.adminDirty&&!confirm('โหลดใหม่จะทิ้งการแก้ไขที่ยังไม่บันทึก ต้องการโหลดใหม่หรือไม่?'))return;setAdmin(await api('getAdminPanel'),state.adminYear);}
 else if(action==='admin-sync-projects'){if(state.adminDirty&&!confirm('มีการแก้ไขยังไม่บันทึก ต้องการโหลดฉบับร่างจากระบบและอัปเดตรายชื่อโครงการหรือไม่?'))return;setAdmin(await api('syncYearProjects',{year:state.adminYear,revision:adminRow().revision}),state.adminYear);toast('อัปเดตโครงการในฉบับร่างแล้ว เกณฑ์เผยแพร่เดิมยังไม่เปลี่ยน');}
 else if(action==='admin-save'||action==='admin-publish'){const publish=action==='admin-publish';if(publish&&!confirm('เผยแพร่เกณฑ์ปี '+state.adminYear+' ให้สมาชิกใช้งาน? ผลที่ส่งไว้แล้วจะคงเกณฑ์เดิม'))return;setAdmin(await api('savePolicyYear',{year:state.adminYear,revision:adminRow().revision,policy:state.adminPolicy,publish}),state.adminYear);toast(publish?'เผยแพร่เกณฑ์แล้ว':'บันทึกฉบับร่างแล้ว');}
 else if(action==='admin-activate'){if(!confirm('เปลี่ยนปีปัจจุบันเป็น '+state.adminYear+'? ผู้ใช้ยังเลือกดูปีเดิมได้'))return;setAdmin(await api('setActivePolicyYear',{year:state.adminYear}),state.adminYear);state.boot=await api('getBootstrap');toast('เปลี่ยนปีปัจจุบันแล้ว');}render();});
}

async function exportTable(kind){await task(async()=>{if(document.fonts){await document.fonts.load('400 22px SVSThai','ภาษาไทย 123');await document.fonts.load('700 26px SVSThai','ภาษาไทย 123');}const overview=kind==='overview',W=overview?2400:2000,margin=36,available=W-margin*2,boot=state.boot,cols=overview?[65,260,500,763,148,148,148,148,148]:[65,360,360,360,783],bands=boot.bands,limits=[`< ${bands[0]}%`,`${bands[0]}–< ${bands[1]}%`,`${bands[1]}–< ${bands[2]}%`,`${bands[2]}–< ${bands[3]}%`,`≥ ${bands[3]}%`],headers=overview?['ข้อ','Corporate Strategic Direction','Individual KPIs','KPI Calculation',...limits.map((x,i)=>'เกรด '+(i+1)+'\n'+x)]:['ข้อ','โครงการ','Sponsor','Manager','สมาชิก'];
 const rows=overview?boot.kpis.map((k,i)=>[String(i+1),k.StrategicDirection||'—',k.KpiId+' '+k.Title+'\n'+(k.IndividualKPI||k.Objective||''),k.Calculation||'',...limits]):boot.projectOverview.map((p,i)=>[String(i+1),p.name,p.sponsors.map(x=>x.name).join('\n'),p.people.filter(x=>x.role==='Manager').map(x=>x.name).join('\n')||'—',p.people.filter(x=>x.role!=='Manager').map((x,i)=>(i+1)+'. '+x.name).join('\n')||'—']);
 const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d'),commands=[],colors=['#fff0ed','#fff5e6','#f5f8e6','#edf7ef','#e4f4ee'];let y=155;
 function wrap(text,width,size){ctx.font=size+'px SVSThai';const out=[];for(const para of String(text||'').split('\n')){let line='';const chars=typeof Intl.Segmenter==='function'?Array.from(new Intl.Segmenter('th',{granularity:'grapheme'}).segment(para),s=>s.segment):Array.from(para);for(const ch of chars){if(line&&ctx.measureText(line+ch).width>width){out.push(line);line=ch;}else line+=ch;}out.push(line);}return out;}
 function row(values,header){const size=header?23:24,all=values.map((v,i)=>wrap(v,cols[i]-26,size)),height=Math.max(70,...all.map(ls=>ls.length*34+24));let x=margin;values.forEach((v,i)=>{commands.push({rect:true,x,y,w:cols[i],h:height,color:overview&&i>=4?colors[i-4]:header?'#e5efea':'#ffffff'});all[i].forEach((t,j)=>commands.push({x:x+(header?cols[i]/2:13),y:y+12+j*34,text:t,size,bold:header,align:header?'center':'left'}));commands.push({rect:true,x,y:y+height-1,w:cols[i],h:1,color:'#ccdcd2'});x+=cols[i];});y+=height;}
 row(headers,true);rows.forEach(r=>row(r,false));y+=50;canvas.width=W;canvas.height=Math.ceil(y);ctx.fillStyle='#fff';ctx.fillRect(0,0,W,y);ctx.fillStyle='#14594e';ctx.fillRect(0,0,W,130);ctx.fillStyle='#fff';ctx.textBaseline='top';ctx.font='700 38px SVSThai';ctx.fillText('SVS Individual-KPI · '+boot.roundId,margin,20);ctx.font='26px SVSThai';ctx.fillText(overview?'ตารางภาพรวมการประเมิน KPI':'ตารางภาพรวมโครงการและผู้รับผิดชอบ',margin,77);commands.forEach(c=>{if(c.rect){ctx.fillStyle=c.color;ctx.fillRect(c.x,c.y,c.w,c.h);}else{ctx.fillStyle='#203c37';ctx.font=(c.bold?'700 ':'400 ')+c.size+'px SVSThai';ctx.textAlign=c.align;ctx.fillText(c.text,c.x,c.y);}});ctx.textAlign='left';ctx.fillStyle='#657a75';ctx.font='19px SVSThai';ctx.fillText('ส่งออก '+dateText(new Date().toISOString()),margin,y-35);
 const blob=await new Promise(r=>canvas.toBlob(r,'image/png'));if(!blob)throw new Error('สร้างภาพไม่สำเร็จ');if(state.tableExport?.url)URL.revokeObjectURL(state.tableExport.url);state.tableExport={url:URL.createObjectURL(blob),title:overview?'ตารางภาพรวม KPI':'ตารางภาพรวมโครงการ',filename:'SVS_Individual_KPI_'+boot.roundId+'_'+kind+'.png'};render();window.scrollTo(0,0);});}
function renderTableExport(){const x=state.tableExport;$('app').innerHTML=`<div class="intro row"><h1>ส่งออก ${esc(x.title)}</h1><div class="actions"><button class="alt" data-action="back-table-export">← กลับตาราง</button><a class="button-link" href="${esc(x.url)}" target="_self" download="${esc(x.filename)}">ดาวน์โหลด PNG</a></div></div><section class="box"><img src="${esc(x.url)}" alt="${esc(x.title)}" style="width:100%;height:auto"></section>`;}

function adminInput(t){const scope=t.dataset.adminScope,i=Number(t.dataset.index),key=t.dataset.key;let value=t.type==='checkbox'?t.checked:t.type==='number'?Number(t.value):t.value;if(['WeightCustomer','WeightNoCustomer','GroupWeight'].includes(key))value/=100;if(scope==='band')state.adminPolicy.bands[i]=Number(value);else state.adminPolicy[scope==='kpi'?'kpis':'criteria'][i][key]=value;state.adminDirty=true;}
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.adminScope){adminInput(t);return;}if(t.dataset.kpiEvidence){state.evidenceByKpi[t.dataset.kpiEvidence]=t.value;markDirty();}else if(t.id==='sharedEvidence'){state.evidence=t.value;markDirty();}else if(t.dataset.notes){answer(t.dataset.notes).Notes=t.value;markDirty();}else if(t.dataset.sponsorNotes){const p=state.sponsor?.projects.find(p=>p.projectId===state.projectId);if(p){p.people.find(x=>x.personId===t.dataset.sponsorNotes).notes=t.value;markDirty();}}});
function headExportData(h){
 const s=h.summary,number=x=>x===null||x===undefined?'—':Number(x).toFixed(2),bands=h.template;
 const rows=s.rows.map((r,i)=>{const b=r.project?bands.percentBands:bands.bands,limits=r.project?[`< ${b[0]}%`,`${b[0]}–< ${b[1]}%`,`${b[1]}–< ${b[2]}%`,`${b[2]}–< ${b[3]}%`,`≥ ${b[3]}%`]:[`1–< ${b[0]}`,`${b[0]}–< ${b[1]}`,`${b[1]}–< ${b[2]}`,`${b[2]}–< ${b[3]}`,`${b[3]}–5`];return [String(i+1),r.id+' · '+r.title+'\n'+(r.meta.individual||''),(r.project?'เฉลี่ยเกรดลูกน้อง ÷ 5 × 100':'เฉลี่ยเกรดลูกน้องก่อนถ่วงน้ำหนัก'),Math.round(r.weight*100)+'%',r.applicable?number(r.mean)+' / 5'+(r.project?'\n'+number(r.percent)+'%':''):'ไม่ใช้',limits.map((x,i)=>(i+1)+': '+x).join('\n'),Number.isInteger(r.grade)?String(r.grade):'—',r.applicable?number(r.weighted):'ไม่ใช้',r.hidden?'จำกัดสิทธิ์':r.applicable?r.included+' จาก '+r.expected+' คน\n'+(r.complete?'ครบแล้ว':'ชั่วคราว'):'ไม่ใช้'];});
 const members=h.members.filter(p=>p.role==='Member').map((p,i)=>[String(i+1),p.name,p.group==='customer'?'ดูแลลูกค้า':p.group==='no_customer'?'ไม่ดูแลลูกค้า':'ยังไม่ระบุ',...s.rows.map(r=>{const k=p.result.kpis.find(k=>k.id===r.id);return k?.hidden?'จำกัดสิทธิ์':!k?'—':!k.applicable?'ไม่ใช้':!k.complete?k.hidden?'จำกัดสิทธิ์':k.project?'รอ Sponsor':'ยังไม่ครบ':String(k.grade)+(r.memberIds.includes(p.personId)?'':'\nรอส่งผล');}),p.result.complete?number(p.result.total)+' / 5'+(!p.submitted?'\nฉบับร่าง':''):'—',({Complete:'ครบแล้ว',WaitingSponsor:'ส่งแล้ว\nรอ Sponsor',Submitted:'ส่งผลแล้ว',Draft:'ฉบับร่าง',NotStarted:'ยังไม่เริ่ม'})[p.status]||'ยังไม่ครบ']);
 return {status:h.privateScores?'ข้อมูลที่เปิดเผย · ไม่แสดง KPI6 และคะแนนรวม':s.complete?'ผลสมบูรณ์':'ผลชั่วคราว — ยังไม่ครบทีม',total:number(s.complete?s.total:s.provisional)+' / 5',rows,members,memberHeaders:['ข้อ','สมาชิก','กลุ่มงาน',...s.rows.map(r=>r.id+'\nเกรดก่อนถ่วงน้ำหนัก'),'Individual-KPI','สถานะ']};
}
