 function row(values,widths,header=false,grades={}){const size=header?24:25,all=values.map((v,i)=>wrap(v,widths[i]-22,size)),height=Math.max(68,...all.map(a=>a.length*35+24));let x=margin;values.forEach((v,i)=>{const grade=grades[i];rect(x,y,widths[i],height,grade?vivid[grade-1]:header?'#e5efea':'#fff');all[i].forEach((text,j)=>commands.push({text,x:header?x+widths[i]/2:x+11,y:y+12+j*35,size,bold:header,color:'#203c37',align:header?'center':'left'}));rect(x,y+height-1,widths[i],1,'#ccdcd2');rect(x+widths[i]-1,y,1,height,'#dde7e1');x+=widths[i];});y+=height;}
