 row(['ข้อ','Individual KPI','หลักการคำนวณ','น้ำหนัก','ค่าเฉลี่ยทีม','สเกลหัวหน้า 1–5','เกรดหัวหน้า','ถ่วงน้ำหนัก','สมาชิกที่ใช้'],widths,true);
