function safeHeadLink(url){return typeof url==='string'&&(url.toLowerCase().startsWith('https://')||url.toLowerCase().startsWith('http://'));}
function headScales(row){const t=state.head.template,b=row.project?t.percentBands:t.bands;return row.project?[`< ${b[0]}%`,`${b[0]}–< ${b[1]}%`,`${b[1]}–< ${b[2]}%`,`${b[2]}–< ${b[3]}%`,`≥ ${b[3]}%`]:[`1–< ${b[0].toFixed(2)}`,`${b[0].toFixed(2)}–< ${b[1].toFixed(2)}`,`${b[1].toFixed(2)}–< ${b[2].toFixed(2)}`,`${b[2].toFixed(2)}–< ${b[3].toFixed(2)}`,`${b[3].toFixed(2)}–5`];}
function headDetails(meta){return `<details class="head-details"><summary>รายละเอียดตามแบบฟอร์มหัวหน้า</summary>${[['ทิศทางกลยุทธ์',meta.strategy],['กลยุทธ์สำคัญ',meta.imperative],['เป้าหมายของทีม',meta.goal],['Individual KPI',meta.individual],['แผนงบประมาณ',meta.budget],['Key Success Action',meta.action],['หน่วยวัด',meta.unit],['ผลปีที่แล้ว',meta.baseline]].filter(([k,v])=>v!==''&&v!==undefined).map(([k,v])=>`<p><b>${esc(k)}:</b> ${esc(v).replace(/\n/g,'<br>')}</p>`).join('')}</details>`;}
